import { useEffect, useState, type ReactNode } from "react";
import { Helmet } from "react-helmet-async";
import { Link } from "wouter";
import { parseGpaiMatrix, safeToolHref, type Matrix, type ProvisionRow } from "@/lib/gpaiMatrix";

/**
 * /gpai — the GPAI evidence matrix: EU AI Act provisions × what this estate's
 * free tooling can actually check today.
 *
 * ONE AUTHORITY. Every provision id, label, status and count on this page is read at
 * runtime from public/interop/gpai-matrix.json (schema csoai.gpai-matrix/0.1) — a file
 * GENERATED by scripts/surface/build-gpai-matrix.mjs from artifacts on the same commit
 * (the frozen 417-provision inventory, the obligation registry, the deadline register,
 * the GPAI crosswalks and card packs). This page derives; it never types an obligation
 * list, an article number or a count. If the matrix cannot be read, the page says
 * UNCHECKABLE — it never falls back to hand-written rows.
 *
 * Status vocabulary is the matrix's own: WIRED means tooling exists today (never that
 * the provision is satisfied); PARTIAL means named and tracked, not measured;
 * UNMEASURED is a first-class answer. Measurement, not certification.
 */

const STATUS_STYLE: Record<string, string> = {
  WIRED: "bg-emerald-50 text-emerald-800 border-emerald-200",
  PARTIAL: "bg-amber-50 text-amber-800 border-amber-200",
  UNMEASURED: "bg-stone-100 text-stone-600 border-stone-300",
};

/** Wouter Link for app routes; plain anchor for files and API paths. */
function MatrixLink({ href, children }: { href: string; children: ReactNode }) {
  const safeHref = safeToolHref(href);
  if (!safeHref) return <span>{children}</span>;
  const isAppPage =
    href.startsWith("/") && !href.startsWith("/api/") && !/\.(json|html)$/.test(href) && !href.startsWith("/.well-known") && !href.startsWith("/packs/");
  return isAppPage ? (
    <Link href={safeHref} className="text-amber-700 underline underline-offset-2 hover:text-amber-600">
      {children}
    </Link>
  ) : (
    <a href={safeHref} className="text-amber-700 underline underline-offset-2 hover:text-amber-600">
      {children}
    </a>
  );
}

function StatusPill({ status }: { status: string }) {
  return (
    <span
      data-status={status}
      className={`inline-block whitespace-nowrap rounded-full border px-2.5 py-0.5 font-mono text-[11px] font-bold uppercase tracking-wide ${STATUS_STYLE[status] ?? "border-stone-300 bg-stone-100 text-stone-600"}`}
    >
      {status}
    </span>
  );
}

export default function GpaiMatrix() {
  const [matrix, setMatrix] = useState<Matrix | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [attempt, setAttempt] = useState(0);
  const [showUnmeasured, setShowUnmeasured] = useState(false);

  useEffect(() => {
    let cancelled = false;
    setErr(null);
    setMatrix(null);
    fetch("/interop/gpai-matrix.json")
      .then(async (r) => {
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        return r.json();
      })
      .then((d: unknown) => {
        const validated = parseGpaiMatrix(d);
        if (!cancelled) setMatrix(validated);
      })
      .catch((e: Error) => {
        if (!cancelled) setErr(e.message || "UNCHECKABLE");
      });
    return () => {
      cancelled = true;
    };
  }, [attempt]);

  const wired = matrix?.provisions.filter((p) => p.status === "WIRED") ?? [];
  const partial = matrix?.provisions.filter((p) => p.status === "PARTIAL") ?? [];
  const unmeasured = matrix?.provisions.filter((p) => p.status === "UNMEASURED") ?? [];
  const scope = matrix?.instrument_scope;
  const cop = matrix?.gpai_code_of_practice;

  return (
    <section className="min-h-screen bg-stone-50 px-5 py-16 text-stone-800">
      <Helmet>
        <title>GPAI evidence matrix | Council of AI — Global Regulation Atlas</title>
        <meta
          name="description"
          content="Explore published evidence and tool references for EU AI Act provisions, with GPAI coverage, source dates and measurement limits."
        />
      </Helmet>
      <section className="mx-auto min-w-0 max-w-4xl [overflow-wrap:anywhere]">
        <p className="font-mono text-xs uppercase tracking-[0.22em] text-amber-700">
          {matrix?.layer ?? "Council of AI — Global Regulation Atlas"} · evidence snapshot{" "}
          {matrix?.as_of ? `· source date ${matrix.as_of}` : err ? "· UNCHECKABLE" : matrix ? "· source date not supplied" : "· loading…"}
        </p>
        <h1 className="mt-3 text-4xl font-black tracking-tight text-stone-900">GPAI evidence matrix</h1>
        <p className="mt-4 leading-7 text-stone-600">
          Explore published evidence and tools related to EU AI Act provisions, including general-purpose
          AI model providers and the voluntary GPAI Code of Practice. Each row identifies its source records
          and current coverage. <strong>WIRED means a tool is referenced; it does not establish that a legal
          duty is satisfied.</strong> Applicability and the adequacy of evidence require separate review.
        </p>

        <nav aria-label="Evidence next steps" className="mt-6 flex flex-wrap gap-3 text-sm">
          <MatrixLink href="/reports/daily-signal/index.html">Daily evidence reports</MatrixLink>
          <MatrixLink href="/gpai-evidence">Explore GPAI evidence packs</MatrixLink>
          <MatrixLink href="/services/">Services and free previews</MatrixLink>
          <MatrixLink href="/gspc-verify">Verify a record</MatrixLink>
        </nav>

        {err ? (
          <div role="alert" className="mt-8 rounded-xl border border-rose-200 bg-rose-50 p-4 text-sm text-rose-700">
            <p>The evidence matrix is currently unavailable. No coverage figures can be shown from this response.</p>
            <p className="mt-2">You can still open the reports, services and verifier above.</p>
            <button type="button" onClick={() => setAttempt(v => v + 1)} className="mt-3 rounded border border-rose-400 px-3 py-2 font-semibold">Try again</button>
          </div>
        ) : !matrix || !scope ? (
          <p className="mt-8 font-mono text-sm text-stone-500">Loading matrix…</p>
        ) : (
          <>
            {/* The grounding funnel — all figures read from the matrix, never typed. */}
            <div className="mt-8 grid gap-4 sm:grid-cols-2">
              <div className="rounded-2xl border border-stone-200 bg-white p-5 shadow-sm">
                <div className="font-mono text-xs uppercase tracking-wide text-stone-500">Inventory coverage</div>
                <p className="mt-2 text-sm leading-6 text-stone-700">
                  The stamped inventory freezes{" "}
                  <strong>{scope.inventory_frozen_provision_counter}</strong> provisions across six instruments, state{" "}
                  <code className="font-mono text-xs">{scope.inventory_state}</code>. This matrix exposes the{" "}
                  <strong>{scope.frozen_identifier_count}</strong> identifiers of {scope.instrument_label} (CELEX{" "}
                  {scope.celex}); the deadline register rows that name this instrument:{" "}
                  <strong>{scope.deadline_register_rows_naming_this_instrument}</strong>. The aggregate corpus root{" "}
                  {scope.corpus_root_recomputed ? "recomputes" : "did NOT recompute"} at generation time.
                </p>
                <p className="mt-2 font-mono text-[11px] leading-5 text-stone-500">{scope.corpus_root}</p>
              </div>
              <div className="rounded-2xl border border-stone-200 bg-white p-5 shadow-sm">
                <div className="font-mono text-xs uppercase tracking-wide text-stone-500">Published coverage</div>
                <div className="mt-3 flex flex-wrap gap-3 text-center">
                  <div className="min-w-[7rem] flex-1 rounded-xl border border-emerald-200 bg-emerald-50 p-3">
                    <div className="font-mono text-2xl font-bold text-emerald-800">{matrix.counts.WIRED}</div>
                    <div className="font-mono text-[11px] uppercase text-emerald-700">WIRED</div>
                  </div>
                  <div className="min-w-[7rem] flex-1 rounded-xl border border-amber-200 bg-amber-50 p-3">
                    <div className="font-mono text-2xl font-bold text-amber-800">{matrix.counts.PARTIAL}</div>
                    <div className="font-mono text-[11px] uppercase text-amber-700">PARTIAL</div>
                  </div>
                  <div className="min-w-[7rem] flex-1 rounded-xl border border-stone-300 bg-stone-100 p-3">
                    <div className="font-mono text-2xl font-bold text-stone-700">{matrix.counts.UNMEASURED}</div>
                    <div className="font-mono text-[11px] uppercase text-stone-600">UNMEASURED</div>
                  </div>
                </div>
                <p className="mt-3 text-sm leading-6 text-stone-600">
                  of {matrix.counts.total} frozen {scope.instrument_label} identifiers. Ties are ties; UNMEASURED is
                  recorded separately from completed measurements.
                </p>
              </div>
            </div>

            {/* Status vocabulary — the matrix's own words, quoted. */}
            <h2 className="mt-12 text-xl font-bold text-stone-900">What the status words mean</h2>
            <div className="mt-4 grid gap-3">
              {Object.entries(matrix.status_vocabulary).map(([word, meaning]) => (
                <div key={word} className="rounded-2xl border border-stone-200 bg-white p-4 shadow-sm">
                  <StatusPill status={word} />
                  <p className="mt-2 text-sm leading-6 text-stone-600">{meaning}</p>
                </div>
              ))}
            </div>

            {/* WIRED rows in full. */}
            <h2 className="mt-12 text-xl font-bold text-stone-900">
              WIRED — {matrix.counts.WIRED} provision{matrix.counts.WIRED === 1 ? "" : "s"} with published tool references
            </h2>
            <div className="mt-4 grid gap-4">
              {wired.map((p) => (
                <ProvisionCard key={p.provision_id} p={p} />
              ))}
            </div>

            {/* PARTIAL rows in full. */}
            <h2 className="mt-12 text-xl font-bold text-stone-900">
              PARTIAL — {matrix.counts.PARTIAL} provision{matrix.counts.PARTIAL === 1 ? "" : "s"} named and tracked,
              not measured
            </h2>
            <p className="mt-2 text-sm leading-6 text-stone-600">
              A served register, obligation record, informative crosswalk, probe record or card pack names each of
              these. That is tracking and mapping — not a measurement of the provision's own duty, and never a
              conformity claim.
            </p>
            <div className="mt-4 grid gap-4">
              {partial.map((p) => (
                <ProvisionCard key={p.provision_id} p={p} />
              ))}
            </div>

            {/* UNMEASURED — the honest majority. */}
            <h2 className="mt-12 text-xl font-bold text-stone-900">
              UNMEASURED — {matrix.counts.UNMEASURED} of {matrix.counts.total} identifiers
            </h2>
            <p className="mt-2 text-sm leading-6 text-stone-600">
              This snapshot retains these provision identifiers and their hashes without a linked measurement.
              Missing labels and evidence remain visible so you can distinguish recorded identifiers from
              requirements that have actually been assessed.
            </p>
            <button
              type="button"
              aria-expanded={showUnmeasured}
              onClick={() => setShowUnmeasured((v) => !v)}
              className="mt-3 rounded-xl border border-stone-300 bg-white px-4 py-2 text-sm font-semibold text-stone-700 hover:bg-stone-100"
            >
              {showUnmeasured ? "Hide" : "List"} the {unmeasured.length} UNMEASURED identifiers
            </button>
            {showUnmeasured ? (
              <div className="mt-4 rounded-2xl border border-stone-200 bg-white p-5 shadow-sm">
                <div className="flex flex-wrap gap-x-4 gap-y-1 font-mono text-xs text-stone-500">
                  {unmeasured.map((p) => (
                    <span key={p.provision_id}>{p.provision_id}</span>
                  ))}
                </div>
              </div>
            ) : null}

            {/* GPAI Code of Practice — grounded, census-only. */}
            <h2 className="mt-12 text-xl font-bold text-stone-900">The GPAI Code of Practice</h2>
            <div className="mt-4 rounded-2xl border border-stone-200 bg-white p-6 shadow-sm">
              <p className="text-sm leading-6 text-stone-600">{cop?.note}</p>
              {cop?.honest_sentence ? (
                <p className="mt-3 border-l-4 border-amber-300 pl-3 text-sm italic leading-6 text-stone-700">
                  "{cop.honest_sentence}"
                </p>
              ) : null}
              {cop?.artifacts?.map((a) => (
                <div key={a.path} className="mt-3 rounded-xl border border-stone-100 bg-stone-50 p-3">
                  <div className="font-mono text-xs text-stone-600">
                    {a.path}
                    {a.as_of ? ` · as_of ${a.as_of}` : ""}
                  </div>
                  {a.measured ? (
                    <div className="mt-1 font-mono text-[11px] text-stone-500">
                      {Object.entries(a.measured)
                        .filter(([, v]) => typeof v === "number" || typeof v === "string")
                        .map(([k, v]) => `${k}=${String(v)}`)
                        .join(" · ")}
                    </div>
                  ) : null}
                </div>
              ))}
            </div>

            {/* Full matrix table — every provision, no omission. */}
            <h2 className="mt-12 text-xl font-bold text-stone-900">The full matrix — {matrix.counts.total} rows</h2>
            <p className="mt-2 text-sm leading-6 text-stone-600">
              Every {scope.instrument_label} identifier the inventory freezes, in id order. Evidence paths name the
              artifact and its SHA-256 at generation time; a reader can re-check any row against those bytes.
            </p>
            <div className="mt-4 overflow-x-auto rounded-2xl border border-stone-200 bg-white shadow-sm">
              <table className="w-full text-left text-sm">
                <thead>
                  <tr className="border-b border-stone-200 font-mono text-[11px] uppercase tracking-wide text-stone-500">
                    <th className="px-4 py-3">Provision</th>
                    <th className="px-4 py-3">Label (from artifacts)</th>
                    <th className="px-4 py-3">Status</th>
                    <th className="px-4 py-3">Tooling wired</th>
                  </tr>
                </thead>
                <tbody>
                  {matrix.provisions.map((p) => (
                    <tr key={p.provision_id} data-status={p.status} className="border-b border-stone-100 last:border-0">
                      <td className="px-4 py-2 font-mono text-xs text-stone-700">{p.provision_id}</td>
                      <td className="px-4 py-2 text-xs text-stone-600">
                        {p.title_or_label_from_artifacts?.[0]?.label ?? "—"}
                      </td>
                      <td className="px-4 py-2">
                        <StatusPill status={p.status} />
                      </td>
                      <td className="px-4 py-2 text-xs">
                        {p.tooling_wired.length ? (
                          <span className="flex flex-wrap gap-x-3 gap-y-1">
                            {p.tooling_wired.map((t) => (
                              <MatrixLink key={t.href} href={t.href}>
                                {t.tool}
                              </MatrixLink>
                            ))}
                          </span>
                        ) : (
                          <span className="text-stone-400">No tool reference</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Discovery doors — machine entry points. */}
            <h2 className="mt-12 text-xl font-bold text-stone-900">Data and source records</h2>
            <div className="mt-4 grid gap-3">
              {matrix.discovery_doors.map((d) => (
                <div key={d.href} className="rounded-2xl border border-stone-200 bg-white p-4 shadow-sm">
                  <div className="text-sm font-bold text-stone-900">
                    <MatrixLink href={d.href}>{d.href}</MatrixLink>{" "}
                    <span className="ml-1 font-mono text-[11px] font-normal uppercase text-stone-400">{d.kind}</span>
                  </div>
                  <p className="mt-1 text-sm leading-6 text-stone-600">{d.note}</p>
                </div>
              ))}
            </div>

            {/* Truth boundaries — the inventory's own, plus the matrix's. */}
            <h2 className="mt-12 text-xl font-bold text-stone-900">Scope and limitations</h2>
            <ul className="mt-4 list-disc space-y-2 pl-5 text-sm leading-6 text-stone-600">
              {matrix.truth_boundaries.map((t, i) => (
                <li key={i}>{t}</li>
              ))}
            </ul>

            {/* What this page is not. */}
            <section className="mt-12 rounded-2xl border border-dashed border-stone-300 bg-stone-100 p-6">
              <h2 className="text-xl font-bold text-stone-900">Using this evidence</h2>
              <p className="mt-3 text-sm leading-6 text-stone-600">
                The matrix describes published evidence and tool references. It does not determine legal
                applicability or compliance. The inventory retains provision hashes, while the original
                source-text bytes remain unresolved. Consult the current official text and review the
                scope of each record before relying on it for a particular obligation.
              </p>
            </section>

            <p className="mt-10 text-sm text-stone-500">
              Verification is free. Check a signed record at{" "}
              <Link href="/gspc-verify" className="text-amber-700 underline">
                /gspc-verify
              </Link>
              ; the Art 50 proof-pattern pane is at{" "}
              <Link href="/art50" className="text-amber-700 underline">
                /art50
              </Link>
              ; the deadline register renders at{" "}
              <Link href="/countdown" className="text-amber-700 underline">
                /countdown
              </Link>
              ; the crosswalk library at{" "}
              <Link href="/crosswalks" className="text-amber-700 underline">
                /crosswalks
              </Link>
              .
            </p>
          </>
        )}
      </section>
    </section>
  );
}

function ProvisionCard({ p }: { p: ProvisionRow }) {
  return (
    <div className="rounded-2xl border border-stone-200 bg-white p-5 shadow-sm">
      <div className="flex flex-wrap items-center gap-3">
        <span className="font-mono text-sm font-bold text-stone-900">{p.provision_id}</span>
        <StatusPill status={p.status} />
        <span className="font-mono text-[11px] uppercase text-stone-400">{p.instrument}</span>
      </div>
      {p.title_or_label_from_artifacts?.length ? (
        <ul className="mt-2 space-y-1">
          {p.title_or_label_from_artifacts.map((l, i) => (
            <li key={i} className="text-sm leading-6 text-stone-700">
              {l.label} <span className="font-mono text-[11px] text-stone-400">— {l.from}</span>
            </li>
          ))}
        </ul>
      ) : (
        <p className="mt-2 text-sm text-stone-500">This snapshot does not provide a title for this provision.</p>
      )}
      <p className="mt-2 text-xs leading-5 text-stone-500">
        <span className="font-mono uppercase tracking-wide">Provision class:</span> {p.provision_class}
      </p>
      {p.tooling_wired.length ? (
        <div className="mt-3 grid gap-2">
          {p.tooling_wired.map((t) => (
            <div key={t.href} className="rounded-xl border border-stone-100 bg-stone-50 p-3">
              <div className="text-sm font-semibold text-stone-800">
                <MatrixLink href={t.href}>{t.tool}</MatrixLink>{" "}
                <span className="ml-1 font-mono text-[11px] font-normal uppercase text-stone-400">{t.kind}</span>
              </div>
              <p className="mt-1 text-xs leading-5 text-stone-600">{t.note}</p>
            </div>
          ))}
        </div>
      ) : null}
      <details className="mt-3">
        <summary className="cursor-pointer font-mono text-[11px] uppercase tracking-wide text-stone-400">
          evidence ({p.evidence.length})
        </summary>
        <ul className="mt-2 space-y-1">
          {p.evidence.map((e, i) => (
            <li key={i} className="break-all font-mono text-[11px] text-stone-500">
              {e}
            </li>
          ))}
        </ul>
      </details>
    </div>
  );
}
